 public const string CancelScript="""
function Dc-Reply($message,$status=''){@{Message=$message;Status=$status}|ConvertTo-Json -Compress}
$p=Join-Path (Join-Path $env:ProgramData 'DomainConsoleCSharp') $id
$name='DomainConsoleCSharp-'+$id
$task=Get-ScheduledTask -TaskName $name -ErrorAction SilentlyContinue
$owned=@(Get-CimInstance Win32_Process -Filter "Name='DomainConsole.Agent.exe'" -ErrorAction Stop|Where-Object {$_.CommandLine -and $_.CommandLine.IndexOf($p,[StringComparison]::OrdinalIgnoreCase) -ge 0})
