  RequiredUpdatesScript31+"[void][Reflection.Assembly]::LoadWithPartialName('Microsoft.UpdateServices.Administration');$s=[Microsoft.UpdateServices.Administration.AdminProxy]::GetUpdateServer($env:COMPUTERNAME,"+(ssl?"$true":"$false")+","+port+");$scope=New-Object Microsoft.UpdateServices.Administration.ComputerTargetScope;$scope.NameIncludes="+PowerShellBridge.Literal(computer.Split('.')[0])+";$targets=@($s.GetComputerTargets($scope)|Where-Object {$_.FullDomainName -eq "+PowerShellBridge.Literal(computer)+" -or $_.FullDomainName.Split('.')[0] -eq "+PowerShellBridge.Literal(computer.Split('.')[0])+"});if(!$targets.Count){throw 'Компьютер не найден в WSUS'};if($targets.Count -ne 1){throw 'Найдено несколько клиентов; уточните полное доменное имя'};$t=$targets[0];$summary=$t.GetUpdateInstallationSummary();$failed=@();$detailError='';if($summary.FailedCount -gt 0){try{$updateScope=New-Object Microsoft.UpdateServices.Administration.UpdateScope;$updateScope.IncludedInstallationStates=[Microsoft.UpdateServices.Administration.UpdateInstallationStates]::Failed;foreach($info in @($t.GetUpdateInstallationInfoPerUpdate($updateScope)|Where-Object {$_.UpdateInstallationState -eq 'Failed'}|Select-Object -First 20)){$update=$info.GetUpdate();$failed+=@{Id=[string]$info.UpdateId;Title=$update.Title;Revision=[int]$update.Id.RevisionNumber;KB=($update.KnowledgebaseArticles -join ',')}}}catch{$detailError=$_.Exception.Message}};$need31=Read-RequiredUpdates31 $t;@{RequiredUpdates=@($need31.RequiredUpdates);RequiredListComplete=$need31.RequiredListComplete;RequiredListError=$need31.RequiredListError;NeededCount=$need31.NeededCount;ApprovedUnknownCount=$need31.ApprovedUnknownCount;ApprovedDownloadedCount=$need31.ApprovedDownloadedCount;ApprovedFailedCount=$need31.ApprovedFailedCount;RequiredComplete=$need31.RequiredComplete;RequiredError=$need31.RequiredError;FailedUpdates=@($failed);FailureDetailsError=$detailError;FullDomainName=$t.FullDomainName;LastReportedUtc=$t.LastReportedStatusTime.ToUniversalTime().ToString('o');LastSyncUtc=$t.LastSyncTime.ToUniversalTime().ToString('o');LastSyncResult=[string]$t.LastSyncResult;UnknownCount=$summary.UnknownCount;NotApplicableCount=$summary.NotApplicableCount;NotInstalledCount=$summary.NotInstalledCount;DownloadedCount=$summary.DownloadedCount;InstalledCount=$summary.InstalledCount;InstalledPendingRebootCount=$summary.InstalledPendingRebootCount;FailedCount=$summary.FailedCount}|ConvertTo-Json -Depth 6 -Compress"),timeout.Token);}
