public static class DirectoryReader {
 public static bool IsDisabled(string flags)=>long.TryParse(flags,out var value)&&(value&2)!=0;
 public static string AdDate(object? value){try{return value!=null&&Convert.ToInt64(value)>0?DateTime.FromFileTimeUtc(Convert.ToInt64(value)).ToString("o"):"";}catch{return "";}}
 public static List<TargetRecord> Read(){
  using var root=new DirectoryEntry("LDAP://RootDSE");var naming=(string?)root.Properties["defaultNamingContext"].Value??throw new Exception("Домен недоступен.");
  using var entry=new DirectoryEntry("LDAP://"+naming);using var search=new DirectorySearcher(entry){Filter="(objectCategory=computer)",PageSize=500,ClientTimeout=TimeSpan.FromSeconds(15),ServerTimeLimit=TimeSpan.FromSeconds(15)};
  search.PropertiesToLoad.AddRange(new[]{"name","dnshostname","distinguishedname","operatingsystem","objectguid","lastlogontimestamp","useraccountcontrol"});using var results=search.FindAll();var list=new List<TargetRecord>();
  foreach(SearchResult r in results){string Get(string n)=>r.Properties[n].Count>0?r.Properties[n][0]?.ToString()??"":"";var name=Get("name");list.Add(new(){AdDisabled=IsDisabled(Get("useraccountcontrol")),Name=name,Host=string.IsNullOrEmpty(Get("dnshostname"))?name:Get("dnshostname"),OU=Regex.Replace(Get("distinguishedname"),@"^CN=(?:\\.|[^,])+,",""),OS=Get("operatingsystem"),Status="Не проверен",DirectoryId=r.Properties["objectguid"].Count>0?new Guid((byte[])r.Properties["objectguid"][0]).ToString():"",AdLastLogonUtc=AdDate(r.Properties["lastlogontimestamp"].Count>0?r.Properties["lastlogontimestamp"][0]:null),AdCollectedUtc=DateTime.UtcNow.ToString("o")});}return list.OrderBy(x=>x.Name).ToList();
 }
